    if wrap < self.subplot_spec[f"n{wrap_dim}s"]:
        self.subplot_spec[f"n{wrap_dim}s"] = wrap
    self.subplot_spec[f"n{flow_dim}s"] = flow
    self.n_subplots = n_subplots
